<template><div class="action-menu"><button class="overflow-button" aria-label="Actions" @click.stop="open=!open">⋯</button><div v-if="open" class="action-popover"><button @click="choose('edit')">Edit</button><button class="danger-text" @click="choose('delete')">Delete</button></div></div></template>
<script setup>import { ref, onMounted, onBeforeUnmount } from 'vue'; const emit=defineEmits(['edit','delete']); const open=ref(false); const choose=a=>{open.value=false;emit(a)}; const close=()=>open.value=false; onMounted(()=>document.addEventListener('click',close)); onBeforeUnmount(()=>document.removeEventListener('click',close))</script>
